# Game status categories
# Change the values as you see fit
STATUS_WIN = 'win'
STATUS_LOSE = 'lose'
STATUS_ONGOING = 'ongoing'

MAX_FAILURES = 10


class Hangman:
    def __init__(self, word):
        self.word = word
        self._guesses = []

    def guess(self, char):
        if self.get_status() != STATUS_ONGOING:
            raise ValueError("The game has already ended.")
        self._guesses.append(char)

    def _state(self):
        seen = set()
        remaining = MAX_FAILURES - 1
        for char in self._guesses:
            if char in self.word and char not in seen:
                seen.add(char)
            else:
                remaining -= 1
        masked = ''.join(char if char in seen else '_' for char in self.word)
        if masked == self.word:
            status = STATUS_WIN
        elif remaining < 0:
            status = STATUS_LOSE
        else:
            status = STATUS_ONGOING
        return remaining, status, masked

    @property
    def remaining_guesses(self):
        return self._state()[0]

    def get_masked_word(self):
        return self._state()[2]

    def get_status(self):
        return self._state()[1]

